/// Lesson sections for the info page — never shown on the practice screen.
const List<TechniqueSection> grooveRock16Lesson = [
  TechniqueSection(
    title: "Why it matters",
    body:
        "Sixteenths on the hi-hat fill every gap the eighth groove leaves open, so the same backbeat suddenly drives harder. It is the groove of mid-tempo rock and pop where the song needs motion without more speed.",
  ),
  TechniqueSection(
    title: "How to play it",
    body:
        "Alternate R L on the hi-hat. On 2 and 4 the left hand hits the snare together with the right-hand hat note, then jumps straight back for the next sixteenth on the hat. The kick plays 1, 3 and the \"and\" of 3, always together with a right-hand hi-hat note.",
  ),
  TechniqueSection(
    title: "Practice tips",
    body:
        "Start line 1 slowly enough that the hi-hat stays even through the backbeat; the stroke before and after the snare tends to go quiet. Line 3 accents the quarters on the hat. Line 5 adds a ghost note on the \"e\" of 3, which falls on a left-hand hat note, so the right hand plays all sixteenths on the hat alone there and the left hand stays on the snare. Line 8 puts the kick on \"e\" and \"a\" — count the sixteenths out loud before you play it.",
  ),
  TechniqueSection(
    title: "Where you hear it",
    body:
        "The Doobie Brothers \"Long Train Runnin'\", Boz Scaggs \"Lowdown\" with Jeff Porcaro, and a great many 70s and 80s soft-rock and pop sixteenth-hat grooves.",
  ),
];
